  const reqStatus=r=>typeof r==="string"?"Do realizacji":(r&&r.status)||"Do realizacji";
  const reqText=r=>typeof r==="string"?r:(r&&r.text)||"";
  const skillPoints=Array.isArray(S.activity.skillPoints)?S.activity.skillPoints:[];
