  const activitySkills=`<section class="work-section activity-skills"><div class="activity-skills-head"><div><div class="section-label">Sprawności</div><p class="table-note">Wybierz sprawności do przećwiczenia na tej zbiórce. Statusy wymagań są wspólne z listą w kontekście zastępu.</p></div>${btn("Dodaj sprawność","open-skill-picker","secondary")}</div>${selectedSkillRecords.length?`<div class="activity-skill-choices">${selectedSkillRecords.map((item,recordIndex)=>{const statusOf=req=>reqStatus(req),textOf=req=>reqText(req);return `<article class="activity-skill-card"><header><b>${esc(item.title)}</b><small>${esc(item.groupLabel||item.group)}</small></header><ul class="activity-skill-points">${(item.requirements||[]).map((requirement,requirementIndex)=>{const text=textOf(requirement),status=statusOf(requirement),done=status==="Ukończono",key=`${item.id}::${requirementIndex}`,checked=skillPoints.includes(key);return `<li class="${done?"is-done":""}">${done?`<span class="activity-skill-status status-${statusToken(status)}">${esc(status)}</span><s>${esc(text)}</s>`:`<span class="activity-skill-status status-${statusToken(status)}">${esc(status)}</span><label><input type="checkbox" data-activity-skill-point value="${esc(key)}" ${checked?"checked":""}/><span>${esc(text)}</span></label>`}</li>`}).join("")}</ul><button type="button" class="activity-skill-remove" data-action="remove-activity-skill" data-skill-id="${esc(item.id)}" aria-label="Usuń ${esc(item.title)} z tej zbiórki">×</button></article>`}).join("")}</div>`:`<p class="context-empty">Nie wybrano jeszcze sprawności — dodaj je przyciskiem „Dodaj sprawność”.</p>`}</section>`;
