let render=renderKompasAppShell;
function setByPath(path,value){const parts=path.split("."),last=parts.pop();let target=S;parts.forEach(x=>target=target[x]);target[last]=value}
function syncUrl(){const q=new URLSearchParams(),f=S.filters;if(f.categories.length)q.set("category",f.categories.join(","));["level","energy","participants"].forEach(k=>f[k]&&q.set(k,f[k]));history.replaceState(null,"",`${location.pathname}${q.toString()?"?"+q:""}`)}
