const label=x=>({odkrywcy:"Odkrywcy",zwiadowcy:"Zwiadowcy",wedrownicy:"Wędrownicy",wszystkie_poziomy:"Wszystkie poziomy",niska:"Niska",srednia:"Średnia",wysoka:"Wysoka"}[x]||x||"Brak danych");
