async function search(){syncUrl();const out=document.getElementById("results"),url=`${API}/api/activities?${query()}`;const cached=await catalogCacheRead("activities",url);if(cached){S.apiData=cached.items;showResults();if(Date.now()-cached.storedAt>=CATALOG_TTL.activities)void refreshActivitiesCatalog(url);return}out.innerHTML=`<div class="empty">Szukam aktywności…</div>`;try{const items=await fetchActivitiesPayload(url);S.apiData=items;await catalogCacheWrite("activities",url,items);showResults()}catch(e){out.innerHTML=`<div class="empty">Nie udało się pobrać aktywności: ${e.message}</div>`}}
const addCatalogActivityToPlan=(item)=>{if(!item)return false;const insertAt=Math.max(0,S.plan.length-1),previous=S.plan[insertAt-1],time=previous?minutesToTime(timeToMinutes(previous.time)+Number(previous.duration||30)):S.team.defaultStart;const row=blankPlanRow(time);row.activity=String(item.title||"");row.description=String(item.description||"");if(item.duration_minutes)row.duration=String(item.duration_minutes);S.plan.splice(insertAt,0,row);recalculatePlanFrom(insertAt);saveDraft();return true};
