document.addEventListener("drop",e=>{const row=e.target.closest("[data-plan-row]");if(!row||S.planDragIndex===null)return;e.preventDefault();const target=+row.dataset.planRow;if(target!==S.planDragIndex){[S.plan[S.planDragIndex],S.plan[target]]=[S.plan[target],S.plan[S.planDragIndex]];recalculatePlanFrom(Math.min(S.planDragIndex,target));saveDraft()}S.planDragIndex=null;render()});
document.addEventListener("dragend",()=>{S.planDragIndex=null;document.querySelectorAll(".is-dragging,.is-drag-over").forEach(node=>node.classList.remove("is-dragging","is-drag-over"))});
document.addEventListener("pointerdown",e=>{const handle=e.target.closest("[data-plan-drag]");if(!handle||e.pointerType==="mouse")return;S.planDragIndex=+handle.dataset.planDrag;handle.setPointerCapture?.(e.pointerId)});
document.addEventListener("pointerup",e=>{if(S.planDragIndex===null||e.pointerType==="mouse")return;const target=e.target.closest("[data-plan-row]")||document.elementFromPoint(e.clientX,e.clientY)?.closest?.("[data-plan-row]");if(target){const to=+target.dataset.planRow;if(to!==S.planDragIndex){[S.plan[S.planDragIndex],S.plan[to]]=[S.plan[to],S.plan[S.planDragIndex]];recalculatePlanFrom(Math.min(S.planDragIndex,to));saveDraft()}}S.planDragIndex=null;render()});
document.addEventListener("change",e=>{if(e.target.matches("[data-plan-time]")){const index=+e.target.dataset.planTime,row=S.plan[index],parsed=parsePlanTime(e.target.value);if(!row)return;if(!parsed){S.toast="Podaj godzinę cyframi, np. 17 lub 1730.";render();setTimeout(()=>{if(S.toast==="Podaj godzinę cyframi, np. 17 lub 1730."){S.toast="";render()}},3200);return}row.time=parsed;recalculatePlanFrom(index);saveDraft();render()}if(e.target.matches("[data-plan-duration]")){const index=+e.target.dataset.planDuration,row=S.plan[index],parsed=parsePlanMinutes(e.target.value);if(!row)return;if(!parsed){S.toast="Podaj czas trwania w minutach (5–600).";render();setTimeout(()=>{if(S.toast==="Podaj czas trwania w minutach (5–600)."){S.toast="";render()}},3200);return}row.duration=parsed;recalculatePlanFrom(index);saveDraft();render()}});
document.addEventListener("click",e=>{const control=e.target.closest("[data-action]");if(!control)return;const action=control.dataset.action;if(action==="cycle-plan-aspect"){const index=+control.dataset.planIndex,row=S.plan[index];if(!row)return;const cycle=["Fizyczny","Intelektualny","Duchowy","Społeczny","Gry i zabawy",""];row.aspect=cycle[(cycle.indexOf(row.aspect)+1)%cycle.length]||"";saveDraft();render()}if(action==="move-plan-row"){const index=+control.dataset.planIndex,direction=control.dataset.direction,other=direction==="up"?index-1:index+1;if(index<0||other<0||other>=S.plan.length)return;[S.plan[index],S.plan[other]]=[S.plan[other],S.plan[index]];recalculatePlanFrom(Math.min(index,other));saveDraft();render()}if(action==="remove-plan-row"){const index=+control.dataset.planIndex;if(index<0||index>=S.plan.length)return;if(S.plan.length===1){S.toast="Plan musi mieć co najmniej jeden wiersz.";render();setTimeout(()=>{if(S.toast==="Plan musi mieć co najmniej jeden wiersz."){S.toast="";render()}},3200);return}S.plan.splice(index,1);recalculatePlanFrom(Math.max(0,index-1));saveDraft();render()}});
document.addEventListener("click",e=>{const control=e.target.closest("[data-action]");if(!control)return;const action=control.dataset.action;if(action==="select-skill-level"){S.skillHistoryLevel=control.dataset.historyLevel;render()}if(action==="add-predefined-skill"){const level=control.dataset.historyLevel,aspect=control.dataset.historyAspect,activity=control.dataset.historySkill;if(!SKILL_CATALOG[aspect]?.includes(activity))return;if(!S.team.skillHistoryRecords.some(item=>item.level===level&&item.aspect===aspect&&item.activity===activity)){const alreadyCompleted=(S.team.skillRecords||[]).some(record=>record.level===level&&(record.groupLabel||record.group)===activity&&Array.isArray(record.requirements)&&record.requirements.length&&record.requirements.every(req=>(typeof req==="string"?"Do realizacji":req.status||"Do realizacji")==="Ukończono"));if(alreadyCompleted){S.toast="Ta grupa jest już ukończona i automatycznie przeniesiona do historii.";render();return}S.team.skillHistoryRecords.push({level,aspect,activity});render()}}if(action==="remove-skill-history"){S.team.skillHistoryRecords.splice(+control.dataset.historyIndex,1);render()}});
document.addEventListener("click",e=>{if(!e.target.closest("[data-action='add-home-task']"))return;S.homeTaskDraft=true;ensureTrailingTask();render();setTimeout(()=>document.querySelector(`[data-task-text="${S.tasks.length-1}"]`)?.focus(),0)});
