const syncAnnualDraftYear=input=>{if(!input?.matches("[data-annual-year]"))return;const year=Number(input.value);if(!Number.isInteger(year)||year<1900||year>2101)return;if(input.dataset.annualYear==="start")S.annualDraft.endYear=String(year+1);else S.annualDraft.startYear=String(year-1);saveDraft();render()};
