document.addEventListener("click",e=>{const control=e.target.closest("[data-action='add-annual-plan']");if(!control)return;e.stopImmediatePropagation();const startYear=Number(S.annualDraft.startYear),endYear=Number(S.annualDraft.endYear);if(!S.annualDraft.topic.trim()||!Number.isInteger(startYear)||!Number.isInteger(endYear)||startYear<1900||endYear>2101||endYear!==startYear+1){S.toast="Podaj temat roczny i dwa kolejne lata.";render();return}if(S.annualPlans.some(plan=>plan.startYear===startYear)){S.toast=`Plan ${startYear} / ${endYear} już istnieje. Wybierz inny rok.`;render();return}const plan={id:`plan-${Date.now()}`,topic:S.annualDraft.topic.trim(),startYear,endYear,yearLabel:`${startYear} / ${endYear}`,months:Array.from({length:12},()=>({direction:"",effect:"",program:"",activities:[]}))};S.annualPlans.push(plan);S.activeAnnualPlanId=plan.id;S.annualDraft={topic:"",startYear:"",endYear:""};S.annualPlanModal=false;saveDraft();render()},true);
document.addEventListener("click",e=>{const control=e.target.closest("[data-action='open-annual-plan-delete-modal'],[data-action='close-annual-plan-delete-modal'],[data-action='confirm-annual-plan-delete']");if(!control)return;const action=control.dataset.action;if(action==="open-annual-plan-delete-modal"){S.annualPlanDeleteId=S.activeAnnualPlanId;render();return}if(action==="close-annual-plan-delete-modal"){S.annualPlanDeleteId=null;render();return}const planIndex=S.annualPlans.findIndex(plan=>plan.id===S.annualPlanDeleteId);if(planIndex<0){S.annualPlanDeleteId=null;render();return}const [removed]=S.annualPlans.splice(planIndex,1);if(S.activity.annualPlanId===removed.id){delete S.activity.annualPlanId;delete S.activity.annualPlanIndex;delete S.activity.annualMonthIndex;delete S.activity.annualActivityIndex;delete S.activity.annualQuarterIndex}const remaining=[...S.annualPlans].sort((a,b)=>a.startYear-b.startYear);S.activeAnnualPlanId=remaining[0]?.id||null;S.annualPlanDeleteId=null;S.toast=`Usunięto plan „${removed.topic}”.`;saveDraft();render();setTimeout(()=>{if(S.toast.startsWith("Usunięto plan")){S.toast="";render()}},3000)});
document.addEventListener("input",e=>{const input=e.target.closest("[data-annual-linked-title],[data-annual-linked-date],[data-annual-linked-start],[data-annual-linked-end]");if(!input)return;const context=annualActivityContext();if(!context)return;if(input.matches("[data-annual-linked-title]")){context.activity.title=input.value;S.activity.title=input.value}else if(input.matches("[data-annual-linked-date]")){context.activity.date=input.value?`${input.value}T${annualActivityStartTime(context.activity)}`:""}else if(input.matches("[data-annual-linked-start]")){context.activity.startTime=input.value;S.activity.startTime=input.value;S.activity.date=context.activity.date?`${String(context.activity.date).split("T")[0]}T${input.value}`:""}else{context.activity.endTime=input.value;S.activity.endTime=input.value}saveDraft()});
document.addEventListener("change",e=>{const input=e.target.closest("[data-annual-linked-title],[data-annual-linked-date],[data-annual-linked-start],[data-annual-linked-end]");if(!input)return;const context=annualActivityContext();if(!context)return;if(input.matches("[data-annual-linked-title]")){context.activity.title=input.value;S.activity.title=input.value}else if(input.matches("[data-annual-linked-date]")){context.activity.date=input.value?`${input.value}T${annualActivityStartTime(context.activity)}`:""}else if(input.matches("[data-annual-linked-start]")){context.activity.startTime=input.value;S.activity.startTime=input.value;S.activity.date=context.activity.date?`${String(context.activity.date).split("T")[0]}T${input.value}`:""}else{context.activity.endTime=input.value;S.activity.endTime=input.value}saveDraft();render()});
document.addEventListener("click",e=>{const control=e.target.closest("[data-action='open-annual-activity-modal'],[data-action='close-annual-activity-modal'],[data-action='save-annual-activity']");if(!control)return;const action=control.dataset.action;if(action==="open-annual-activity-modal"){const planIndex=Number(control.dataset.planIndex),plan=S.annualPlans[planIndex];if(!plan)return;const mode=control.dataset.mode||"month",monthIndex=Number(control.dataset.monthIndex),yearOf=mi=>mi>=8?plan.startYear:plan.endYear;let date="",mi;if(mode==="month"&&monthIndex>=0){mi=monthIndex;date=`${yearOf(mi)}-${String(mi+1).padStart(2,"0")}-01`}else{const now=new Date();mi=now.getMonth();date=`${now.getFullYear()}-${String(now.getMonth()+1).padStart(2,"0")}-${String(now.getDate()).padStart(2,"0")}`}S.annualActivityDraft={mode,planIndex,monthIndex:mi,date,title:""};S.annualActivityModal=true;render();return}if(action==="close-annual-activity-modal"){S.annualActivityModal=false;S.annualActivityDraft=null;render();return}if(action==="save-annual-activity"){const draft=S.annualActivityDraft;if(!draft)return;const date=draft.date||"",title=(draft.title||"").trim();if(!date){S.toast="Podaj datę aktywności.";render();return}if(!title){S.toast="Podaj nazwę aktywności.";render();return}const plan=S.annualPlans[draft.planIndex];if(!plan)return;const monthIndex=new Date(date+"T00:00:00").getMonth(),month=plan.months[monthIndex];if(!month)return;month.activities=Array.isArray(month.activities)?month.activities:[];if(plan.months.some(item=>(item.activities||[]).some(activity=>activity.date===date))){S.toast=`Data ${date} jest już użyta w tym planie.`;render();return}month.activities.push({date,title});S.annualActivityModal=false;S.annualActivityDraft=null;S.toast=`Dodano „${title}” do planu.`;saveDraft();render();setTimeout(()=>{S.toast="";render()},3000)}},true);
document.addEventListener("input",e=>{const input=e.target.closest("[data-annual-draft-title]");if(!input||!S.annualActivityDraft)return;S.annualActivityDraft.title=input.value;saveDraft()});
document.addEventListener("change",e=>{const month=e.target.closest("[data-annual-draft-month]"),date=e.target.closest("[data-annual-draft-date]");if(!S.annualActivityDraft)return;if(month){const mi=Number(month.value),plan=S.annualPlans[S.annualActivityDraft.planIndex],year=(plan&&mi>=8?plan.startYear:plan&&mi<8?plan.endYear:S.annualActivityDraft.year)||new Date().getFullYear();S.annualActivityDraft.monthIndex=mi;S.annualActivityDraft.date=`${year}-${String(mi+1).padStart(2,"0")}-01`;render()}else if(date){S.annualActivityDraft.date=date.value;if(date.value)S.annualActivityDraft.monthIndex=new Date(date.value+"T00:00:00").getMonth();render()}});
