document.addEventListener("drop",e=>{const day=e.target.closest(".annual-calendar-day"),drag=S.annualDrag;if(!day||!drag)return;e.preventDefault();const targetDate=day.querySelector("time[datetime]")?.getAttribute("datetime"),sourcePlan=S.annualPlans?.[drag.planIndex],sourceMonth=sourcePlan?.months?.[drag.monthIndex],activity=sourceMonth?.activities?.[drag.activityIndex];if(!targetDate||!activity)return;activity.date=targetDate;sourceMonth.activities.splice(drag.activityIndex,1);sourcePlan.months[Number(targetDate.slice(5,7))-1].activities.push(activity);S.annualDrag=null;saveDraft();render()});
