document.addEventListener("click",e=>{const control=e.target.closest("[data-action='cycle-skill-requirement']");if(!control)return;const record=S.team.skillRecords[+control.dataset.skillRecordIndex];if(!record)return;const normalized={odkrywcy:"Odkrywcy",zwiadowcy:"Zwiadowcy",wedrownicy:"Wędrownicy"}[String(record.level||S.team.group||"").normalize("NFD").replace(/[\u0300-\u036f]/g,"").toLowerCase()];if(normalized)record.level=normalized;const reqIndex=+control.dataset.skillRequirementIndex;if(Number.isInteger(reqIndex)&&record.requirements?.[reqIndex]){const req=record.requirements[reqIndex];const current=typeof req==="string"?"Do realizacji":(req.status||"Do realizacji");const next={"Do realizacji":"W trakcie","W trakcie":"Ukończono","Ukończono":"Do realizacji"}[current]||"Do realizacji";record.requirements[reqIndex]=typeof req==="string"?{text:req,status:next}:{...req,status:next};completeActivitySkillPoint(record.id,reqIndex,next==="Ukończono")}},true);
