function problem(){const experiments=S.problem.experiments;const experimentRows=experiments.map((item,index)=>`<article class="experiment-editor"><div class="experiment-editor-head"><h3>Eksperyment #${index+1}</h3><button type="button" class="trial-remove" data-action="remove-experiment" data-experiment-index="${index}" aria-label="Usuń eksperyment ${index+1}" ${experiments.length===1?"disabled":""}>×</button></div>${area("Co zmieniam",`problem.experiments.${index}.test`,item.test,"Jedna konkretna zmiana.")}${area("Czego się spodziewamy",`problem.experiments.${index}.expectation`,item.expectation,"Jaki będzie efekt?")}</article>`).join("");return `<section class="page">${pageHead("PROBLEM #4","Nawigacja i współpraca","Pracuj nad jednym skutkiem, który realnie możesz zmienić.")}<section class="work-section">${area("Problem","problem.statement",S.problem.statement,"Zadawaj pytania dlaczego do skutku.")}${area("Hipoteza przyczyny","problem.hypothesis",S.problem.hypothesis,"")}</section><section id="experiment" class="work-section"><div class="section-label">EKSPERYMENTY</div><p class="table-note">Minimum jeden eksperyment. Dodaj kolejne, jeśli chcesz sprawdzić kilka zmian.</p><div class="experiment-editor-list">${experimentRows}</div><div class="row-actions">${btn("+ Dodaj eksperyment","add-experiment","secondary")}</div></section><section class="work-section accent-section"><div class="section-label">OCENA I DECYZJA</div>${radioList("problem.hypothesisEval",["Wsparta","Osłabiona","Nierozstrzygnięta"],S.problem.hypothesisEval)}${radioList("problem.decision",["Zachowaj","Zmień","Powtórz","Zamknij"],S.problem.decision)}</section><div class="save-bar">${btn("Wróć do zbiórki","activity","secondary")}</div></section>`}
function activity(){const a=S.activity;const tabs=[["planning","Planowanie"],["summary","Podsumowanie"],["insights","Problemy"]];const results=S.problem.experiments.map((item,index)=>`<article class="summary-experiment"><div class="summary-experiment-head"><p class="experiment-kicker">Eksperyment #${index+1}</p><b>${esc(item.test||"Nie opisano jeszcze eksperymentu.")}</b></div>${item.expectation?`<p class="summary-experiment-expectation">Spodziewany efekt: ${esc(item.expectation)}</p>`:""}<label class="field"><span>Obserwacja tej próby</span><textarea data-field="activity.experimentResults.${index}.observation" placeholder="Zapisz samą obserwację">${esc(a.experimentResults[index]?.observation||"")}</textarea></label></article>`).join("");const content=S.activityCard==="summary"?`<section class="work-section"><div class="section-label">PODSUMOWANIE PRZEBIEGU I EKSPERYMENTU</div>${area("Co wydarzyło się podczas aktywności","activity.whatHappened",a.whatHappened,"Zapisz obserwowalny przebieg, odchylenia i ważne momenty.")}${results}${area("Wynik eksperymentu","activity.result",a.result,"Co faktycznie pokazały próby?")}${area("Opinia skautów","activity.scouts",a.scouts,"Co uczestnicy zauważyli lub powiedzieli?")}${area("Wnioski z przebiegu","activity.reflection",a.reflection,"Czego dowiedzieliście się o prowadzeniu aktywności?")}${area("Wnioski z eksperymentu","activity.takeaway",a.takeaway,"Co wynika z dowodów i co warto zmienić dalej?")}</section>`:S.activityCard==="insights"?`<section id="problems" class="work-section"><div class="section-label">PROBLEMY DO DALSZEJ PRACY</div><p class="table-note">Zapisz problem, który warto zaadaptować do kolejnej aktywności, oraz decyzję wynikającą z eksperymentu.</p>${area("Problem","problem.statement",S.problem.statement,"Co wymaga dalszej pracy?")}${area("Hipoteza przyczyny","problem.hypothesis",S.problem.hypothesis,"Co prawdopodobnie powoduje problem?")}${area("Wniosek z eksperymentu","problem.conclusion",S.problem.conclusion,"Co wynika z prób?")}${area("Kolejny krok","activity.nextStep",a.nextStep,"Jaką zmianę podejmiecie dalej?")}</section>`:`<section class="work-section"><div class="section-label">CEL ZBIÓRKI</div>${area("Cel / oczekiwany efekt","activity.goal",a.goal,"Po czym poznasz osiągnięcie celu?")}<div class="experiment-card-list">${S.problem.experiments.map((item,index)=>`<article class="experiment-card"><small>EKSPERYMENT #${index+1}</small><b>${esc(item.test||"Nie opisano jeszcze eksperymentu.")}</b></article>`).join("")}</div></section>`;return `<section class="page wide">${pageHead("AKTYWNOŚĆ #"+a.number,a.title,"Karta pracy podzielona na trzy krótkie etapy.")}<nav class="activity-tabs">${tabs.map(([key,label])=>`<button class="${S.activityCard===key?"active":""}" data-card="${key}">${label}</button>`).join("")}</nav>${content}</section>`}
document.addEventListener("click",e=>{const control=e.target.closest("[data-action]");if(!control)return;const action=control.dataset.action;if(action==="add-experiment"){S.problem.experiments.push({test:"",expectation:""});S.activity.experimentResults.push({observation:""});saveDraft();render()}if(action==="remove-experiment"&&S.problem.experiments.length>1){const index=Number(control.dataset.experimentIndex);S.problem.experiments.splice(index,1);S.activity.experimentResults.splice(index,1);saveDraft();render()}});
const annualActivityDisplayObserver=new MutationObserver(()=>{if(S.view!=="annual")return;document.querySelectorAll(".horizon-activity").forEach(row=>{if(row.querySelector(".annual-activity-summary"))return;const title=row.querySelector("input[data-field$='.title']"),date=row.querySelector("input[data-field$='.date']");if(!title||!date)return;const summary=document.createElement("div");summary.className="annual-activity-summary";const dateText=date.value?new Intl.DateTimeFormat("pl-PL",{day:"2-digit",month:"2-digit",year:"numeric"}).format(new Date(`${date.value}T00:00:00`)):"Bez daty";summary.innerHTML=`<time>${dateText}</time><strong>${title.value.trim()||"Aktywność bez nazwy"}</strong>`;row.prepend(summary)})});annualActivityDisplayObserver.observe(root,{childList:true,subtree:true});
if(S.view==="annual")render();
