const experimentEditPopup=()=>{
  if(S.experimentEditIndex===null||S.experimentEditIndex===undefined)return "";
  const item=S.experimentEditDraft||S.problem.experiments[S.experimentEditIndex]||{};
  return `<div class="modal-overlay experiment-edit-overlay" role="dialog" aria-modal="true" aria-label="Edytuj eksperyment"><section class="modal experiment-edit-modal"><div class="experiment-edit-head"><div><p class="eyebrow">EKSPERYMENT #${Number(S.experimentEditIndex)+1}</p><h2>Edytuj eksperyment</h2></div><button type="button" class="trial-remove" data-action="close-experiment-editor" aria-label="Zamknij edycję eksperymentu">×</button></div><label class="field"><span>Co zmieniam</span><textarea data-experiment-edit-field="test" placeholder="Jedna konkretna zmiana.">${esc(item.test||"")}</textarea></label><label class="field"><span>Czego się spodziewam</span><textarea data-experiment-edit-field="expectation" placeholder="Jaki będzie efekt?">${esc(item.expectation||"")}</textarea></label><div class="modal-actions"><button type="button" class="btn secondary" data-action="close-experiment-editor">Anuluj</button><button type="button" class="btn" data-action="save-experiment-editor">Zapisz eksperyment</button></div></section></div>`;
};
const decorateExperimentCards=()=>{
  if(S.view!=="activity"||S.activityCard!=="planning")return;
  document.querySelector(".experiment-card-list + .text-action[data-target='experiment']")?.remove();
  document.querySelectorAll(".experiment-card").forEach((card,index)=>{
    card.dataset.action="open-experiment-editor";
    card.dataset.experimentIndex=String(index);
    card.setAttribute("role","button");
    card.setAttribute("tabindex","0");
    card.setAttribute("aria-label",`Edytuj eksperyment ${index+1}`);
  });
  document.querySelector(".annual-goal-readonly-section .table-note")?.remove();
  if(!document.querySelector(".experiment-edit-overlay")&&S.experimentEditIndex!==null)root.insertAdjacentHTML("beforeend",experimentEditPopup());
};
const baseRenderWithExperimentEditor=render;
render=()=>{baseRenderWithExperimentEditor();decorateExperimentCards()};
document.addEventListener("click",e=>{
  const control=e.target.closest("[data-action]");
  if(!control)return;
  const action=control.dataset.action;
  if(action==="open-experiment-editor"){
    const index=Number(control.dataset.experimentIndex),item=S.problem.experiments[index];
    if(!item)return;
    S.experimentEditIndex=index;
    S.experimentEditDraft={test:item.test||"",expectation:item.expectation||""};
    decorateExperimentCards();
  }
  if(action==="close-experiment-editor"){
    S.experimentEditIndex=null;S.experimentEditDraft=null;document.querySelector(".experiment-edit-overlay")?.remove();
  }
  if(action==="save-experiment-editor"){
    const index=S.experimentEditIndex,item=S.problem.experiments[index];
    if(!item||!S.experimentEditDraft)return;
    item.test=S.experimentEditDraft.test||"";item.expectation=S.experimentEditDraft.expectation||"";
    S.experimentEditIndex=null;S.experimentEditDraft=null;saveDraft();render();
  }
});
