document.addEventListener("change",e=>{const input=e.target.closest("[data-dod-tab]");if(!input)return;const tab=input.dataset.dodTab,index=Number(input.dataset.dodIndex);if(!S.dodOverrides[tab]||!Number.isInteger(index))return;S.dodOverrides[tab][index]=input.checked;syncDodProgress();saveDraft();render()});
window.addEventListener("click",e=>{const control=e.target.closest("[data-action='toggle-route-stage']");if(!control)return;e.preventDefault();e.stopImmediatePropagation();openNearestStage({dataset:{dodStage:control.dataset.routeStage,dodIndex:"0"}})},true);
