const expStatusClass=status=>({"Do przygotowania":"exp-prep","Aktywny":"exp-active","Do oceny":"exp-review","Zakończony":"exp-done"}[status]||"exp-prep");
const ensureExperimentHypothesis=()=>{S.problem.experiments.forEach(item=>{if(item.hypothesis===undefined)item.hypothesis=""})};
const expFiltered=()=>{const query=String(S.experimentsQuery||"").trim().toLocaleLowerCase("pl-PL");return S.problem.experiments.map((item,index)=>({item,index})).filter(({item})=>{if(S.experimentsStatus&&item.status!==S.experimentsStatus)return false;if(!query)return true;return[item.test,item.expectation,item.conclusion,item.owner,item.operatingRule].some(value=>String(value||"").toLocaleLowerCase("pl-PL").includes(query))})};
const expCounts=status=>S.problem.experiments.filter(item=>item.status===status).length;
const expCardHtml=({item,index})=>`<article class="exp-card" role="button" tabindex="0" data-action="open-experiment" data-experiment-index="${index}" aria-label="Otwórz eksperyment ${index+1}: ${esc(item.test||"bez opisu")}"><div class="exp-card-head"><span class="exp-card-kicker">EKSPERYMENT #${index+1}</span><span class="exp-status ${expStatusClass(item.status)}">${esc(item.status)}</span></div><h3>${esc(item.test||"Nie opisano jeszcze eksperymentu.")}</h3>${item.expectation?`<p class="exp-card-expectation">Spodziewany efekt: ${esc(item.expectation)}</p>`:""}<div class="exp-card-meta">${item.owner?`<span>Odpowiedzialny: ${esc(item.owner)}</span>`:""}${Array.isArray(item.trials)&&item.trials.length?`<span>Próby: ${item.trials.length}</span>`:""}${item.activityTitle?`<span>${esc(item.activityTitle)}</span>`:""}</div><span class="exp-card-open">Otwórz →</span></article>`;
const expCardListHtml=()=>{const filtered=expFiltered();return filtered.length?filtered.map(expCardHtml).join(""):`<p class="context-empty">Brak eksperymentów spełniających filtry.</p>`};
const experimentsView=()=>`<section class="page wide exp-list-page">${pageHead("EKSPERYMENTY","Eksperymenty w pracy","Rozwijaj jedną zmianę naraz i weryfikuj ją próbami.")}<section class="work-section exp-problem-section"><div class="section-label">PROBLEM W PRACY</div><button type="button" class="exp-problem-card" data-action="open-problem-context" aria-label="Otwórz kontekst problemu"><div><b>${esc(S.problem.statement||"Opisz problem, nad którym pracujecie.")}</b>${S.problem.hypothesis?`<small>Hipoteza: ${esc(S.problem.hypothesis)}</small>`:""}</div><span class="exp-problem-card-open">Kontekst i 5×dlaczego →</span></button></section><section class="work-section"><div class="section-label">EKSPERYMENTY</div><div class="exp-filters"><label class="field"><span>Szukaj</span><input data-exp-query value="${esc(S.experimentsQuery||"")}" placeholder="Szukaj po zmianie, wniosku…" aria-label="Szukaj eksperymentów"/></label><div class="exp-status-filters" role="group" aria-label="Filtruj po statusie">${["","Do przygotowania","Aktywny","Do oceny","Zakończony"].map(status=>`<button type="button" class="exp-status-filter ${S.experimentsStatus===status?"is-active":""}" data-action="exp-filter-status" data-exp-status="${status}" aria-pressed="${S.experimentsStatus===status}">${status?esc(status):"Wszystkie"}<span>${status?expCounts(status):S.problem.experiments.length}</span></button>`).join("")}</div></div><div class="exp-card-list" id="exp-card-list">${expCardListHtml()}</div><div class="row-actions">${btn("+ Nowy eksperyment","exp-add","secondary")}</div></section></section>`;
const experimentView=()=>{const index=Math.min(Math.max(Number(S.experimentIndex)||0,0),Math.max(S.problem.experiments.length-1,0));const item=S.problem.experiments[index];if(!item)return experimentsView();const trials=(Array.isArray(item.trials)?item.trials:[]).map((trial,j)=>`<div class="trial-row exp-trial-row"><div class="trial-head exp-trial-head"><input data-field="problem.experiments.${index}.trials.${j}.activityNumber" value="${esc(trial.activityNumber||"")}" aria-label="Numer aktywności próby ${j+1}" placeholder="Nr aktywności"/><input data-field="problem.experiments.${index}.trials.${j}.activityDate" value="${esc(trial.activityDate||"")}" aria-label="Data próby ${j+1}" placeholder="Data"/><button type="button" class="trial-remove" data-action="exp-remove-trial" data-experiment-index="${index}" data-trial-index="${j}" aria-label="Usuń próbę ${j+1}">×</button></div><textarea data-field="problem.experiments.${index}.trials.${j}.note" aria-label="Obserwacja próby ${j+1}" placeholder="Co zaobserwowano podczas tej próby?">${esc(trial.note||"")}</textarea></div>`).join("");const observation=S.activity.experimentResults?.[index]?.observation||"";const linked=String(item.activityId||"")===String(S.activity.number||"");return `<section class="page wide exp-detail-page">${pageHead(`EKSPERYMENT #${index+1}`,esc(item.test||"Nowy eksperyment"),"Prowadź zmianę w czterech krokach: kontekst, przygotowanie, próby, ocena i decyzja.")}<div class="exp-detail-status"><span class="exp-status exp-status-lg ${expStatusClass(item.status)}">${esc(item.status)}</span></div><section class="work-section"><div class="section-label">A · KONTEKST</div><div class="exp-context-block"><p class="exp-context-problem"><b>Problem:</b> ${esc(S.problem.statement||"—")}</p>${S.problem.hypothesis?`<p class="exp-context-hypothesis"><b>Hipoteza:</b> ${esc(S.problem.hypothesis)}</p>`:""}<button type="button" class="text-action" data-action="open-problem-context">Zobacz pełny kontekst →</button></div>${input("Odpowiedzialny",`problem.experiments.${index}.owner`,item.owner,"Kto prowadzi ten eksperyment?")}<div class="exp-activity-link"><span class="exp-link-label">Powiązanie ze zbiórką</span><button type="button" class="text-action ${linked?"is-linked":""}" data-action="toggle-exp-activity-link" data-experiment-index="${index}" aria-pressed="${linked}">${linked?`Powiązano z aktywnością #${S.activity.number}`:"Powiąż z bieżącą aktywnością"}</button></div></section><section class="work-section"><div class="section-label">B · ZMIANA</div>${area("Co zmieniam","problem.experiments."+index+".test",item.test,"Jedna konkretna zmiana.")}${area("Czego się spodziewam","problem.experiments."+index+".expectation",item.expectation,"Jaki będzie efekt, jeśli hipoteza jest trafna?")}${area("Hipoteza tej zmiany","problem.experiments."+index+".hypothesis",item.hypothesis||"","Dlaczego ta zmiana ma zadziałać?")}</section><section class="work-section"><div class="section-label">C · PRZYGOTOWANIE</div>${area("Kryteria oceny","problem.experiments."+index+".evaluationCriteria",item.evaluationCriteria,"Po czym poznacie, że zmiana zadziałała?")}${input("Data przeglądu","problem.experiments."+index+".reviewDate",item.reviewDate,"np. 2026-09-01")}</section><section class="work-section"><div class="section-label">D · PRÓBY</div>${trials||`<p class="context-empty">Brak prób. Dodaj pierwszą próbę, aby zacząć testować zmianę.</p>`}<div class="row-actions">${btn("+ Dodaj próbę","exp-add-trial","secondary",`data-experiment-index="${index}"`)}</div>${area("Obserwacja zbierana po zbiórce","activity.experimentResults."+index+".observation",observation,"Zapisz samą obserwację – bez interpretacji.")}</section><section class="work-section accent-section" id="evaluation"><div class="section-label">E · OCENA I DECYZJA</div><div class="exp-eval-block">${radioList("problem.experiments."+index+".hypothesisEval",["Wsparta","Osłabiona","Nierozstrzygnięta"],item.hypothesisEval)}</div>${area("Wniosek","problem.experiments."+index+".conclusion",item.conclusion,"Co wynika z prób?")}${area("Zasada na przyszłość","problem.experiments."+index+".operatingRule",item.operatingRule,"Co wchodzi na stałe do działania?")}<div class="exp-eval-block">${radioList("problem.experiments."+index+".decision",["Zachowaj","Zmień","Powtórz","Zamknij"],item.decision)}</div></section><div class="save-bar">${btn("Wróć do eksperymentów","experiments","secondary")}${btn("Usuń eksperyment","exp-remove","secondary",`data-experiment-index="${index}"`)}</div></section>`};
const problemCardView=()=>{const why=Array.from({length:5},(_,i)=>`<div class="why-row"><span>${i+1}.</span><input data-field="problem.why.${i}" aria-label="Dlaczego ${i+1}" placeholder="Dlaczego?" value="${esc(S.problem.why?.[i]||"")}"/><b>→</b></div>`).join("");const links=S.problem.experiments.map((item,index)=>`<button type="button" class="exp-problem-link" data-action="open-experiment" data-experiment-index="${index}" aria-label="Otwórz eksperyment ${index+1}"><span class="exp-problem-link-kicker">EKSPERYMENT #${index+1}</span><b>${esc(item.test||"Nie opisano jeszcze eksperymentu.")}</b><span class="exp-status ${expStatusClass(item.status)}">${esc(item.status)}</span></button>`).join("")||`<p class="context-empty">Brak eksperymentów.</p>`;return `<section class="page wide problem-card-page">${pageHead("PROBLEM","Kontekst problemu","Analiza przyczyny i powiązane eksperymenty.")}<section class="work-section"><div class="section-label">PROBLEM + 5 × DLACZEGO?</div>${area("Problem","problem.statement",S.problem.statement,"Zadawaj pytania dlaczego do skutku.")}<div class="why-list">${why}</div></section><section class="work-section accent-section"><div class="section-label">HIPOTEZA PRZYCZYNY</div>${area("Co prawdopodobnie powoduje problem?","problem.hypothesis",S.problem.hypothesis,"")}</section><section class="work-section"><div class="section-label">POWIĄZANE EKSPERYMENTY</div><div class="exp-problem-links">${links}</div></section><div class="save-bar">${btn("Wróć do eksperymentów","experiments","secondary")}</div></section>`};
content=()=>({home:homeV2,activity:activityPlanning,experiments:experimentsView,experiment:experimentView,problem:problemCardView,annual:annualV2,team:teamV2,skills,finder,picker:pickerView})[S.view]();
