const decorateExpNavigation=()=>{if(S.view!=="activity"||S.activityCard!=="planning")return;document.querySelector(".experiment-card-list + .text-action[data-target='experiment']")?.remove();document.querySelector(".annual-goal-readonly-section .table-note")?.remove();document.querySelectorAll(".experiment-card").forEach((card,index)=>{card.dataset.action="open-experiment";card.dataset.experimentIndex=String(index);card.setAttribute("role","button");card.setAttribute("tabindex","0");card.setAttribute("aria-label",`Otwórz eksperyment ${index+1}`)})};
