document.addEventListener("click",e=>{const control=e.target.closest("[data-action]");if(!control)return;const action=control.dataset.action;if(action==="exp-add"){S.problem.experiments.push({test:"",expectation:"",hypothesis:"",owner:"",activityId:"",activityTitle:"",evaluationCriteria:"",trials:[],conclusion:"",operatingRule:"",reviewDate:"",decision:"",hypothesisEval:"Nierozstrzygnięta"});S.activity.experimentResults.push({observation:""});S.experimentIndex=S.problem.experiments.length-1;saveDraft();S.view="experiment";render();return}if(action==="exp-remove"){if(S.problem.experiments.length<=1)return;const index=Number(control.dataset.experimentIndex);S.problem.experiments.splice(index,1);S.activity.experimentResults.splice(index,1);S.experimentIndex=Math.min(S.experimentIndex,S.problem.experiments.length-1);S.view="experiments";saveDraft();render();return}if(action==="open-experiment"){S.experimentIndex=Number(control.dataset.experimentIndex);S.view="experiment";render();return}if(action==="experiments"){S.view="experiments";render();return}if(action==="open-problem-context"){S.view="problem";render();return}if(action==="exp-filter-status"){S.experimentsStatus=S.experimentsStatus===control.dataset.expStatus?"":control.dataset.expStatus;render();return}if(action==="exp-add-trial"){const index=Number(control.dataset.experimentIndex),item=S.problem.experiments[index];if(!item)return;if(!Array.isArray(item.trials))item.trials=[];item.trials.push({activityNumber:"",activityDate:"",note:""});saveDraft();render();return}if(action==="exp-remove-trial"){const index=Number(control.dataset.experimentIndex),trialIndex=Number(control.dataset.trialIndex),item=S.problem.experiments[index];if(!item||!Array.isArray(item.trials))return;item.trials.splice(trialIndex,1);saveDraft();render();return}if(action==="toggle-exp-activity-link"){const index=Number(control.dataset.experimentIndex),item=S.problem.experiments[index];if(!item)return;const linked=String(item.activityId||"")===String(S.activity.number||"");if(linked){item.activityId="";item.activityTitle=""}else{item.activityId=String(S.activity.number||"");item.activityTitle=S.activity.title||""}saveDraft();render();return}});
document.addEventListener("input",e=>{const query=e.target.closest("[data-exp-query]");if(query){S.experimentsQuery=query.value;const list=document.getElementById("exp-card-list");if(list)list.innerHTML=expCardListHtml();else render();return}const field=e.target.dataset.field;if(field&&field.startsWith("problem.experiments.")){syncExperimentToProblem();saveDraft()}});
document.addEventListener("change",e=>{const field=e.target.dataset.field;if(!field||!field.startsWith("problem.experiments."))return;if(field.endsWith(".hypothesisEval"))S.problem.hypothesisEvalTouched=true;if(field.endsWith(".decision"))S.problem.decisionTouched=true;syncExperimentToProblem();syncDodProgress();saveDraft();const page=document.querySelector(".exp-detail-page");if(page){const item=S.problem.experiments[Number(field.split(".")[2])||0];if(item){const title=page.querySelector(".page-title h1");if(title)title.textContent=esc(item.test||"Nowy eksperyment");const chip=page.querySelector(".exp-detail-status .exp-status");if(chip){chip.textContent=esc(item.status);chip.className="exp-status exp-status-lg "+expStatusClass(item.status)}}}});
